// Builds the job matrix of the breakpoint gate from the Lean split (golden/gate/schedule.jsonl, generated by
// lean/Fw/Gate/ScheduleGolden.lean from Fw.Gate.Schedule.choose). Glue only: how many jobs there are, how many probes each
// takes and which whole sweeps ride on which job is Lean's decision; this script deals the probe ids by matrix order and
// verifies that the result runs every probe and every sweep exactly once.
//   node .github/scripts/gate-jobs.mjs [--params measured] [--runs 2] [--free 8] [--engines both|chromium|playwright-webkit]
//                                      [--parts id,...] [--golden <file>] [--shards <file>] [--gen <path>]
// --params measured (gate-shard-balance) reads golden/gate/shards.jsonl instead: Lean (Fw.Gate.Shard, LPT over measured
// unit costs) names the probe ids and whole sweeps of every job, so nothing is dealt here.
// Prints one JSON object {"include":[{"engine","job","probes","sweeps"}...],"engines":[...]} on stdout: `probes` goes to
// `cli.mjs run --probes`, `sweeps` to `--sweeps` ("none" = nothing). Progress goes to stderr.
// --params / --runs / --free choose the golden line: the time set (base, cached, reduced), the number r of runs sharing the
// pool and the number m of runners free for them (4, 8, 12 or 20 of the account's 20). --parts narrows to the Lean scope of those parts (spec.scopeFor), as gate-shards.mjs did: the probes of the
// scope are dealt over fewer probe jobs (a job keeps the full run's probe count, ceil(124 / k)), the sweeps outside the scope
// are dropped, and a job left with nothing is not started.
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';

const argv = process.argv.slice(2);
const arg = (n, d) => { const i = argv.indexOf(`--${n}`); return i < 0 ? d : argv[i + 1]; };
const die = (m, code = 1) => { console.error(`gate-jobs: ${m}`); process.exit(code); };

const paramsName = arg('params', 'measured');
const runs = Number(arg('runs', '2'));
const free = Number(arg('free', '8'));
const enginesArg = arg('engines', 'both');
const goldenPath = resolve(arg('golden', 'packages/contracts/golden/gate/schedule.jsonl'));
const genPath = resolve(arg('gen', 'apps/site/src/breakpoints.gen.json'));
if (!Number.isInteger(runs) || runs < 1 || runs > 3) die('--runs must be 1, 2 or 3 (the golden has those)', 2);
const engineList = { both: ['chromium', 'playwright-webkit'], chromium: ['chromium'], 'playwright-webkit': ['playwright-webkit'] }[enginesArg];
if (!engineList) die(`--engines: bad value ${enginesArg}`, 2);

// --params measured: the LPT plan of Fw.Gate.Shard over the measured unit costs (golden/gate/shards.jsonl, generated by
// lean/Fw/Wire/ShardGolden.lean). Lean lists every job's probe ids and whole sweeps; this script passes them through.
const measured = paramsName === 'measured';
const shardsPath = resolve(arg('shards', 'packages/contracts/golden/gate/shards.jsonl'));
const golden = readFileSync(measured ? shardsPath : goldenPath, 'utf8').split('\n').filter(Boolean).map((l) => JSON.parse(l));
const line = golden.find((g) => g.params === paramsName && g.r === runs && g.m === free);
if (!line) die(`no golden line for params=${paramsName} r=${runs} free=${free}`, 2);
const chosen = measured ? line : line.chosen;
if (!chosen.grahamOk) die('the golden line does not satisfy the Graham bound');

const spec = await import(pathToFileURL(resolve('packages/gate-breakpoints/src/spec.mjs')).href);
const gen = JSON.parse(readFileSync(genPath, 'utf8'));
const ids = gen.matrix.probes.map((p) => p.id);
if (new Set(ids).size !== ids.length) die('duplicate probe ids in the gen file');
if (ids.length !== gen.matrix.loadsPerEngine) die(`gen says ${gen.matrix.loadsPerEngine} loads, file has ${ids.length}`);
for (const id of ids) if (!/^[A-Za-z0-9._-]+$/.test(id)) die(`unsafe probe id ${id}`);

// The Lean sweeps are named by their first word; map them to the spec ids (each exactly one).
const sweepIds = spec.sweepDefs(gen).map((s) => s.id);
const sweepOf = new Map();
for (const id of sweepIds) {
  const short = id.split('-')[0];
  if (sweepOf.has(short)) die(`two spec sweeps start with ${short}`);
  sweepOf.set(short, id);
}

let scope = null;
const partsArg = arg('parts', undefined);
if (partsArg) {
  const known = Object.keys(JSON.parse(readFileSync(resolve('packages/gate-breakpoints/src/anchors.json'), 'utf8')).parts);
  const want = partsArg.split(',').map((x) => x.trim()).filter(Boolean);
  const bad = want.filter((p) => !known.includes(p));
  if (want.length === 0 || bad.length > 0) die(`--parts: ${want.length === 0 ? 'empty list' : `unknown part ${bad.join(', ')}`}; known: ${known.join(', ')}`, 2);
  scope = spec.scopeFor(spec.selectParts(known, want), gen);
  if (scope) console.error(`probe scope: ${scope.probes.length} probes, sweeps ${scope.sweeps.join(', ') || 'none'}`);
}

const runIds = scope ? scope.probes : ids;
const runSweeps = scope ? scope.sweeps : sweepIds;
const include = [];
for (const eng of engineList) {
  const jobs = chosen.jobs.filter((j) => j.engine === eng).sort((a, b) => a.slot - b.slot);
  if (jobs.length === 0) die(`the golden line has no jobs for ${eng}`);
  if (measured) {
    // Lean's jobs as they are; a narrowed run keeps each job's probes and sweeps inside the scope and drops empty jobs.
    for (const j of jobs) {
      const mine = j.probes.filter((id) => runIds.includes(id));
      const sw = j.sweeps.map((s) => sweepOf.get(s) ?? die(`unknown Lean sweep ${s}`)).filter((id) => runSweeps.includes(id));
      if (mine.length === 0 && sw.length === 0) continue;
      include.push({ engine: eng, job: `j${j.slot}`, probes: mine.length ? mine.join(',') : 'none', sweeps: sw.length ? sw.join(',') : 'none' });
    }
    continue;
  }
  const k = jobs[0].k;
  const probeJobs = jobs.filter((j) => j.slot < k);
  if (probeJobs.length !== k) die(`${eng}: expected ${k} probe jobs, golden has ${probeJobs.length}`);
  // Probe deal: full run = Lean's k jobs, matrix index mod k (Lean's job sizes are floor(124/k) + [i < 124 mod k]).
  // Narrowed run = the same job size ceil(124/k), so a few probes are not spread over k runners that each pay a setup.
  const per = Math.ceil(ids.length / k);
  const m = scope ? (runIds.length === 0 ? 0 : Math.max(1, Math.min(k, Math.ceil(runIds.length / per)))) : k;
  const dealt = Array.from({ length: k }, () => []);
  runIds.forEach((id, i) => dealt[i % Math.max(m, 1)].push(id));
  for (const j of jobs) {
    const mine = j.slot < k ? dealt[j.slot] : [];
    if (!scope && mine.length !== j.probes) die(`${eng} slot ${j.slot}: Lean says ${j.probes} probes, the deal gives ${mine.length}`);
    const sw = j.sweeps.map((s) => sweepOf.get(s) ?? die(`unknown Lean sweep ${s}`)).filter((id) => runSweeps.includes(id));
    if (mine.length === 0 && sw.length === 0) continue;
    include.push({ engine: eng, job: `j${j.slot}`, probes: mine.length ? mine.join(',') : 'none', sweeps: sw.length ? sw.join(',') : 'none' });
  }
}

// Verify what the CLI will pick (the filters of run.mjs: probes `id.includes(o) || block === o`, sweeps `id.includes(o)`).
const pickProbes = (list) => gen.matrix.probes.filter((p) => list.some((o) => p.id.includes(o) || p.block === o)).map((p) => p.id);
const pickSweeps = (list) => sweepIds.filter((id) => list.some((o) => id.includes(o)));
for (const eng of engineList) {
  const mine = include.filter((j) => j.engine === eng);
  const seenP = new Map();
  const seenS = new Map();
  for (const j of mine) {
    const want = j.probes === 'none' ? [] : j.probes.split(',');
    const got = want.length ? pickProbes(want) : [];
    if (got.length !== want.length || got.some((id) => !want.includes(id))) die(`${eng} ${j.job}: the --probes filter picks ${got.length} ids, expected ${want.length}`);
    for (const id of got) { if (seenP.has(id)) die(`${eng}: probe ${id} in two jobs`); seenP.set(id, j.job); }
    const ws = j.sweeps === 'none' ? [] : j.sweeps.split(',');
    const gs = ws.length ? pickSweeps(ws) : [];
    if (gs.length !== ws.length || gs.some((id) => !ws.includes(id))) die(`${eng} ${j.job}: the --sweeps filter picks ${gs}, expected ${ws}`);
    for (const id of gs) { if (seenS.has(id)) die(`${eng}: sweep ${id} in two jobs`); seenS.set(id, j.job); }
  }
  if (seenP.size !== runIds.length || runIds.some((id) => !seenP.has(id))) die(`${eng}: the jobs do not cover the probes (${seenP.size} of ${runIds.length})`);
  if (seenS.size !== runSweeps.length || runSweeps.some((id) => !seenS.has(id))) die(`${eng}: the jobs do not cover the sweeps (${[...seenS.keys()]} of ${runSweeps})`);
}

process.stdout.write(JSON.stringify({ include, engines: engineList }) + '\n');
console.error(`${paramsName} r=${runs} free=${free}: ${include.length} jobs: ${include.map((j) => `${j.engine}/${j.job}=${j.probes === 'none' ? 0 : j.probes.split(',').length}p+${j.sweeps === 'none' ? 0 : j.sweeps.split(',').length}s`).join(' ')}`);
